<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { message } from '../feedback'
import AppDialog from '../components/AppDialog.vue'
import type { Account } from '../types'
import { BulbOutlined, BgColorsOutlined, FolderOpenOutlined, CopyOutlined, SafetyCertificateOutlined } from '@ant-design/icons-vue'
import { useAppStore } from '../store'
const store = useAppStore()
const uid = ref('')
const accountDialog = ref(false)
const mergeDialog = ref(false)
const deleteTarget = ref<Account | null>(null)
const form = reactive({ action: 'create', uid: '', name: '', target: '' })
const active = computed(() => store.state?.accounts.find(account => account.key === store.state?.activeAccount))
watch(() => store.state?.activeAccount, () => { uid.value = store.state?.summary.uid || '' }, { immediate: true })
watch(() => store.state?.summary.uid, value => { uid.value = value || '' })
function edit(action: 'create'|'rename') { form.action = action; form.uid = ''; form.name = action === 'rename' ? active.value?.name || '' : ''; accountDialog.value = true }
async function saveAccount() {
  if (form.uid && !/^\d{5,15}$/.test(form.uid)) { message.error('UID 必须是 5–15 位数字'); return }
  const result = await store.invoke('accounts.'+form.action, { key: active.value?.key, uid: form.uid, name: form.name })
  if (result !== undefined) accountDialog.value = false
}
function remove() { if (active.value) deleteTarget.value = { ...active.value } }
async function confirmDelete() {
  if (!deleteTarget.value || store.busy) return
  const result = await store.invoke('accounts.remove', { key: deleteTarget.value.key })
  if (result !== undefined) deleteTarget.value = null
}
async function merge() { const result = await store.invoke('accounts.merge', { key: active.value?.key, target: form.target }); if (result !== undefined) mergeDialog.value = false }
async function copyArchive() { const value = await store.invoke('shell.copyArchive'); if(value) message.success('归档路径已复制') }
async function checkUpdate() { store.updateOpen = true; await store.invoke('updates.check') }
</script>
<template>
  <section class="page settings-page"><div class="page-heading"><div><h1>数据与设置</h1><p class="muted">管理你的账号、归档和使用偏好。</p></div></div>
    <section class="panel settings-section"><div class="section-label"><h2>界面主题</h2><p>只有白与黑，选择会在下次启动恢复。</p></div><div class="theme-options"><button :class="{ active: store.colorMode === 'light' }" @click="store.savePreferences({ color_mode: 'light' })" aria-label="白色主题"><span class="theme-preview light-preview"><i></i><b></b><em></em></span><span><BulbOutlined aria-hidden="true"/>白色</span><small>晴空与清晰的记录</small></button><button :class="{ active: store.colorMode === 'dark' }" @click="store.savePreferences({ color_mode: 'dark' })" aria-label="黑色主题"><span class="theme-preview dark-preview"><i></i><b></b><em></em></span><span><BgColorsOutlined aria-hidden="true"/>黑色</span><small>安静的夜间档案</small></button></div><div class="setting-line"><span>卡池详情列数</span><a-segmented :value="store.state?.preferences.pool_columns || 0" :options="[{label:'自动',value:0},{label:'一列',value:1},{label:'两列',value:2}]" @change="(value: unknown) => store.savePreferences({pool_columns: value === 0 ? null : Number(value) as 1|2})"/></div></section>
    <section class="panel settings-section"><div class="section-label"><h2>账号</h2><p>每个 UID 独立保存记录、垫抽与保底。</p></div><a-select class="account-select" :value="store.state?.activeAccount" :disabled="store.busy" :options="store.state?.accounts.map(account => ({ value: account.key, label: account.label+' · '+Math.max(0,account.groups)+' 组' }))" @change="(value: unknown) => store.invoke('accounts.switch',{key:String(value)})"/><a-space wrap><a-button :disabled="store.busy" @click="edit('create')">新建账号</a-button><a-button :disabled="store.busy" @click="edit('rename')">重命名</a-button><a-button :disabled="store.busy || (store.state?.accounts.length || 0) < 2" @click="form.target=''; mergeDialog=true">合并到…</a-button><a-button danger :disabled="store.busy || (store.state?.accounts.length || 0) < 2" @click="remove">删除</a-button></a-space><p class="muted">当前账号：{{ active?.label }} · 已有记录不能通过修改 UID 重新归属。</p></section>
    <section class="panel settings-section"><div class="section-label"><h2>UID 与分享文件</h2><p>分享与上传使用根目录中的 &lt;UID&gt;.json，导出时会核对记录归属。</p></div><a-input v-model:value="uid" placeholder="输入游戏 UID" :disabled="store.busy" aria-label="游戏 UID"/><a-space wrap><a-button :disabled="store.busy" @click="store.invoke('uid.save',{uid})">保存 UID</a-button><a-button :disabled="store.busy" @click="store.capture('uid.read')">从游戏读取 UID</a-button><a-button type="primary" :disabled="store.busy || !store.state?.summary.pulls" @click="store.invoke('records.share',{uid})">导出发送文件</a-button></a-space><small class="muted">当前 UID：{{ store.state?.summary.uid || '尚未设置' }}</small></section>
    <section class="panel settings-section"><div class="section-label"><h2>游戏版本</h2><p>国际服、日服和台服共用进程名，请按实际客户端选择。</p></div><a-radio-group :value="store.state?.server" :disabled="store.busy" option-type="button" :options="store.state?.servers.map(server => ({value:server.key,label:server.label}))" @change="(event: {target:{value:string}}) => store.invoke('server.save',{key:event.target.value,manual:true})"/><div class="setting-line"><span class="muted">{{ store.state?.serverManual ? '手动指定，已记住' : '自动识别' }}</span><a-button :disabled="store.busy" @click="store.invoke('server.save',{key:store.state?.server,manual:false})">自动识别</a-button></div></section>
    <section class="panel settings-section"><div class="section-label"><h2>自动上传与更新</h2><p>两个开关独立保存，切换账号不影响偏好。</p></div><div class="setting-line"><div><strong>自动上传到蕾姆</strong><p>抓取或导入成功后上传；记录没有变化时跳过。</p></div><a-switch :checked="store.state?.preferences.auto_upload" @change="(value: unknown) => store.savePreferences({auto_upload:!!value})"/></div><div class="setting-line"><div><strong>软件自动更新</strong><p>启动时检查，下载前展示说明，校验完成后再确认安装。</p></div><a-switch :checked="store.state?.preferences.auto_update" @change="(value: unknown) => store.savePreferences({auto_update:!!value})"/></div><div class="setting-line"><span>更新渠道</span><a-select :value="store.state?.preferences.update_channel" :disabled="['downloading','verifying','installing'].includes(store.update.status)" :options="[{label:'测试版',value:'beta'},{label:'稳定版',value:'stable'}]" @change="(value: unknown) => store.savePreferences({update_channel: value as 'beta'|'stable'})"/></div><a-space wrap><a-button @click="checkUpdate">检查更新</a-button><a-button v-if="store.update.status === 'ready'" type="primary" @click="store.updateOpen = true">更新已就绪</a-button><a-button v-else-if="['downloading','verifying'].includes(store.update.status)" @click="store.updateOpen = true">查看下载进度</a-button></a-space><p class="muted">上传成功后仍需向蕾姆发送绑定指令确认正式更新。</p></section>
    <section class="panel settings-section"><div class="section-label"><h2>归档与资源</h2><p class="archive-path">{{ store.state?.archivePath }}</p></div><a-space wrap><a-button @click="store.invoke('shell.openExports')"><FolderOpenOutlined aria-hidden="true"/>打开数据目录</a-button><a-button @click="copyArchive"><CopyOutlined aria-hidden="true"/>复制路径</a-button><a-button :disabled="store.busy" @click="store.invoke('archive.backup')"><SafetyCertificateOutlined aria-hidden="true"/>创建备份</a-button><a-button :disabled="store.busy" @click="store.importFiles()">导入记录</a-button><a-button :disabled="store.busy || !store.state?.summary.pulls" @click="store.exportRecords()">导出 JSON / CSV</a-button><a-button :disabled="store.busy" @click="store.invoke('resources.sync')">同步名称与头像</a-button></a-space><p class="muted">旧档和备份会保留；损坏归档或 UID 归属不明时停止写入。</p></section>
    <AppDialog transition-name="stella-dialog" mask-transition-name="stella-mask" v-model:open="accountDialog" variant="form" :title="form.action === 'create' ? '新建账号' : '重命名账号'" ok-text="保存" cancel-text="取消" @ok="saveAccount"><a-form layout="vertical"><a-form-item v-if="form.action === 'create'" label="UID（可留空）"><a-input v-model:value="form.uid"/></a-form-item><a-form-item label="备注名"><a-input v-model:value="form.name" :maxlength="100"/></a-form-item></a-form></AppDialog>
    <AppDialog transition-name="stella-dialog" mask-transition-name="stella-mask" v-model:open="mergeDialog" variant="form" title="合并到另一个账号" ok-text="确认合并" cancel-text="取消" :ok-button-props="{disabled:!form.target}" @ok="merge"><a-alert type="warning" show-icon message="只能合并归属已确认且 UID 相同的归档；两边会先备份。"/><a-select v-model:value="form.target" class="merge-select" :options="store.state?.accounts.filter(account => account.key !== active?.key).map(account => ({value:account.key,label:account.label}))"/></AppDialog>
    <AppDialog :open="!!deleteTarget" title="删除这个账号？" variant="danger" :footer="null" @cancel="deleteTarget = null"><p class="stella-dialog-description">主归档和账号目录会移入保留目录，可以人工恢复。其他账号的数据不受影响。</p><div class="stella-context-card"><span>即将移入保留目录</span><strong>{{ deleteTarget?.label }}</strong><small>{{ deleteTarget?.uid ? 'UID '+deleteTarget.uid : '尚未绑定 UID' }} · {{ deleteTarget?.groups || 0 }} 组记录</small></div><div class="dialog-actions"><a-button @click="deleteTarget = null">取消</a-button><a-button type="primary" danger :disabled="store.busy" @click="confirmDelete">确认删除</a-button></div></AppDialog>
  </section>
</template>
